steps = [
    step("同一批 5 个商品 item(id、含中文的 name、price、tags 列表、note 有的是 None),FEEDS 同时写六种格式:json 422 字节(开头 “[” 再每个 item 一行)、jsonlines 415 字节(一行一个 JSON,None 写成 null)、csv 141 字节(表头 id,name,price,tags,note,列表 tags 被拼成 \"a,b\"、None 变成空)、xml 669 字节(<items>…)、pickle 432 字节、marshal 354 字节;stats feedexport/success_count/FileFeedStorage = 6。", t=tl(S(1)), mark=lidx(S(1), 'o.csv', 'o.xml'), done=lidx(S(1), 'o.json', 'o.jsonl', 'o.pickle', 'o.marshal'), b=bars([['json', 422, '422 字节'], ['jsonlines', 415, '415 字节'], ['csv', 141, '141 字节'], ['xml', 669, '669 字节'], ['pickle', 432, '432 字节'], ['marshal', 354, '354 字节']], 669, mark=[2], done=[0, 1, 3, 4, 5]), kv=KV([['json / jsonlines', '中文被转义,None → null'], ['csv', '表头取自第一个 item,列表拼成 "a,b"'], ['xml / pickle / marshal', 'xml 最大(669 字节),marshal 最小(354 字节)']], ['csv'])),
    step("编码与缩进:json 格式默认把中文转义成 \\uXXXX(a.json 170 字节),设 encoding='utf-8' 输出原字符(b.json 158 字节);indent=2 缩进成多行(c.json 206 字节);csv 默认就是 UTF-8(d.csv 与 e.csv 同样 71 字节、都显示中文);全局设置 FEED_EXPORT_ENCODING=utf-8 与逐个 feed 设 encoding 效果相同。", t=tl(S(2)), mark=lidx(S(2), 'a.json', 'b.json', 'c.json'), done=lidx(S(2), 'd.csv', 'e.csv', 'FEED_EXPORT_ENCODING'), kv=KV([['json 默认', '中文转义成 \\uXXXX'], ['encoding = utf-8', '输出原字符'], ['csv 默认', 'UTF-8,不转义'], ['FEED_EXPORT_ENCODING', '全局默认值']], ['json 默认'])),
    step("fields 选列并排序:csv 的 fields=['price','id'] 得到表头 price,id;json 的 fields=['name','id'] 每个对象只剩这两个键,顺序按 fields;不写 fields 时 csv 的表头取第一个 item 的键(id,name,price,tags,note)。item 键不一致时:{a}、{a,b}、{b} 三个 item,csv 表头只有 a,第二个 item 的 b 被丢掉,第三个 item 变成一个空值行;jsonlines 则每行原样保留各自的键。", t=tl(S(3)), mark=lidx(S(3), 'item 键不一致'), done=lidx(S(3), 'a.csv', 'b.json', 'c.csv'), kv=KV([['fields', '选列并决定顺序'], ['csv 不写 fields', '表头 = 第一个 item 的键'], ['键不一致', 'csv 丢掉多出的键;jsonlines 原样保留']], ['csv 不写 fields'])),
    step("再跑一次同一个文件:本地文件默认是追加——o.jsonl 第 1 次 2 行、第 2 次 4 行;overwrite=True 的 p.jsonl 两次都是 2 行;json 格式追加更糟:q.json 里是两个拼接的 JSON 数组,json.loads 报 “Extra data: line 4 column 2 (char 170)”,文件不再是合法 JSON。要每次重新生成,用 overwrite=True。", t=tl(S(4)), mark=lidx(S(4), '第 2 次运行后', 'q.json(json'), done=lidx(S(4), '第 1 次运行后'), kv=KV([['本地文件默认', '追加'], ['overwrite = True', '每次重写'], ['json + 追加', '得到两个拼接的数组,不是合法 JSON']], ['json + 追加'])),
    step("批量输出:URI 里写 %(batch_id)d 并设 batch_item_count=10,25 个 item 拆成 out-1-demo.jsonl、out-2-demo.jsonl、out-3-demo.jsonl 三个文件,各 10、10、5 行,stats 里 success_count = 3。URI 里还可以用 %(name)s(spider 名)、%(time)s、%(batch_time)s 等占位符。", t=tl(S(5)), mark=lidx(S(5), 'batch_item_count=10'), kv=KV([['batch_item_count = 10', '25 个 item → 3 个文件'], ['占位符', '%(batch_id)d、%(name)s、%(time)s …'], ['stats', 'success_count = 3']], ['batch_item_count = 10'])),
    step("其它开关:item_classes 里写不存在的类(nonexistent.Class)直接让启动失败(ModuleNotFoundError: No module named 'nonexistent'),连 all.jsonl 都没生成;item_classes=['builtins.dict'] 只导出 dict 类型(3 行),['scrapy.Item'] 过滤掉了全部 dict item(文件存在但 0 行);postprocessing=GzipPlugin 压缩输出:100 个 item 解压后 8606 字节,文件 864 字节;URI 写 “stdout:” 输出到标准输出(StdoutFeedStorage);没有任何 item 时默认 store_empty=True 仍写文件(e1.json 4 字节、e3.csv 和 e4.jsonl 0 字节),store_empty=False 则不创建文件。", t=tl(S(6)), mark=lidx(S(6), 'item_classes 里写不存在', 'GzipPlugin', '没有任何 item'), done=lidx(S(6), 'item_classes: dict', 'stdout:'), kv=KV([['item_classes', '只导出这些类的 item;写错类名启动失败'], ['postprocessing', 'GzipPlugin:8606 → 864 字节'], ['stdout:', '输出到标准输出'], ['store_empty = False', '没有 item 就不创建文件']], ['item_classes'])),
]
